<script setup>
import { computed, onMounted, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import Button from 'primevue/button'; import Card from 'primevue/card'; import Divider from 'primevue/divider'; import ConfirmDialog from 'primevue/confirmdialog'; import { useConfirm } from 'primevue/useconfirm'; import StatusTag from '../../components/StatusTag.vue'; import LoadingState from '../../components/LoadingState.vue'; import api, { errorMessage } from '../../services/api'; import { formatDate } from '../../utils/status'
const route = useRoute(), router = useRouter(), confirm = useConfirm(), request = ref(null), error = ref(''), saving = ref(false); const steps=['OPEN','ASSIGNED','IN_PROGRESS','RESOLVED','CLOSED']; const position = computed(() => steps.indexOf(request.value?.status))
const load=async()=>{try{request.value=(await api.get(`/service-requests/${route.params.id}`)).data}catch(e){error.value=errorMessage(e)}}; const close=()=>confirm.require({message:'Xác nhận công việc đã được hoàn thành?',header:'Xác nhận hoàn thành',acceptLabel:'Xác nhận',accept:async()=>{saving.value=true;try{await api.patch(`/service-requests/${request.value.id}/confirm`);await load()}finally{saving.value=false}}}); onMounted(load)
</script>
<template><div class="page-heading"><div><Button label="Quay lại" icon="pi pi-arrow-left" text @click="router.push('/resident/requests')" /><h1 v-if="request">{{request.code}} · {{request.title}}</h1><p>Theo dõi toàn bộ quá trình xử lý.</p></div><StatusTag v-if="request" :value="request.status" /></div><div v-if="error" class="error-panel">{{error}}</div><LoadingState v-else-if="!request" /><div v-else class="content-card"><div class="timeline"><div v-for="(step,index) in steps" :key="step" class="timeline-step" :class="{complete:index<=position}"><StatusTag :value="step" /><small>{{ index===0 ? formatDate(request.createdAt) : index===1 ? formatDate(request.assignedAt) : index===2 ? formatDate(request.startedAt) : index===3 ? formatDate(request.resolvedAt) : formatDate(request.closedAt) }}</small></div></div><Divider /><div class="card-grid"><div><h3>Thông tin yêu cầu</h3><p>{{request.description}}</p><div class="card-meta"><span><i class="pi pi-tags" /> {{request.category || 'Khác'}}</span><span><i class="pi pi-clock" :class="{overdue:request.overdue}" /> Hạn xử lý: {{formatDate(request.dueAt)}}</span></div></div><div><h3>Kết quả xử lý</h3><p>{{request.resolutionNote || 'Kỹ thuật viên chưa cập nhật kết quả.'}}</p><Button v-if="request.status==='RESOLVED'" label="Xác nhận hoàn thành" icon="pi pi-check" :loading="saving" @click="close" /></div></div></div></template>
